entries[140337] = { ["name"] = "Imported Tough Jerky", ["text"] = "Use: Restores ( 38 * 18 / 5) health over 18 sec. Must remain seated while eating.\n\"The excessive use of a salt makes this extremely popular in the small country towns of Azeroth.\"\nSell Price:" }
entries[140338] = { ["name"] = "Mana-Wrapped Goretusk Liver Pie", ["text"] = "Use: Restores ( 38 * 21 / 5) health over 21 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 1 Stamina and Versatility for 15 min.\n\"Homemade in a land called Westfall, this pie was mana-wrapped to preserve freshness.\"\nSell Price:" }
entries[140339] = { ["name"] = "Hormone Free - Alterac Swiss", ["text"] = "Use: Restores ( 375 * 30 / 5) health over 30 sec.\nMust remain seated while eating.\n\"The salesman claimed this was a favorite of the famed court of Alterac.\"\nSell Price:" }
entries[140340] = { ["name"] = "Bottled - Carbonated Water", ["text"] = "Use: Restores ( 917 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\n\"They somehow managed to inject bubbles without the use of magic...\"\nSell Price:" }
