entries[140456] = { ["name"] = "Crest of Carnage", ["text"] = "Binds when picked up\nUnique\nUse: Unlocks a new color for the war-torn variation of your artifact.\n\"A medal adorning the brutal and unrelenting who emerge bloodied and victorious, time and time again.\"" }
