entries[140458] = { ["name"] = "Lasher Seed", ["text"] = "Binds when picked up\nUse: Provides a significant increase to character experience. Does not work for players over level 49.\n\"It's the color of dried blood, and prickly.\"" }
entries[140459] = { ["name"] = "Moon Lily", ["text"] = "Binds when picked up\n\"A thank-you gift from one of the priestesses at the temple.\"\nSell Price:" }
entries[140460] = { ["name"] = "Thisalee's Fighting Claws", ["text"] = "Binds when picked up\n\"They're sharp enough to cut through sea giant flesh, and apparently did.\"\nSell Price:" }
entries[140461] = { ["name"] = "Battered Trophy", ["text"] = "Binds when picked up\n\"The harpies dragged it back to their nest as treasure many years ago. The inscriptions have long since worn off.\"\nSell Price:" }
entries[140462] = { ["name"] = "Draketaming Spurs", ["text"] = "Binds when picked up\n\"Cruel and sharp, they only fit vrykul-sized boots.\"\nSell Price:" }
entries[140463] = { ["name"] = "Broken Eredar Blade", ["text"] = "Binds when picked up\n\"The material is not as high quality as one might expect.\"\nSell Price:" }
entries[140464] = { ["name"] = "Miniature Totem", ["text"] = "Binds when picked up\nUse: Provides a significant increase to character experience. Does not work for players over level 49.\n\"Crudely whittled, it may have been made by a child.\"\nSell Price:" }
entries[140465] = { ["name"] = "Duskpelt Hide", ["text"] = "Binds when picked up\nUse: Provides a significant increase to character experience. Does not work for players over level 49.\n\"Even the most rigorous treatment wouldn't make it any softer.\"" }
entries[140466] = { ["name"] = "Corroded Eternium Rose", ["text"] = "Binds when picked up\n\"Someone threw this into the sewers, and the chemicals damaged it badly.\"\nSell Price:" }
entries[140467] = { ["name"] = "Fel-Infused Shell", ["text"] = "Binds when picked up\n\"Fel magic melted right into the shell of the poor, deceased creature that once lived inside.\"\nSell Price:" }
entries[140468] = { ["name"] = "Eagle Eggshell Fragment", ["text"] = "Binds when picked up\n\"It was broken a long time ago, but was once massive.\"\nSell Price:" }
entries[140469] = { ["name"] = "Felslate Arrowhead", ["text"] = "Binds when picked up\n\"Someone tried to shoot back. Key word: tried.\"\nSell Price:" }
entries[140470] = { ["name"] = "Ancient Gilnean Locket", ["text"] = "Binds when picked up\n\"From a time long past, before the curse and the wall.\"\nSell Price:" }
entries[140471] = { ["name"] = "Lord Shalzaru's Relic", ["text"] = "Binds when picked up\n\"Once the property of Naga royalty, discovered below the waves off the coast of Azsuna.\"\nSell Price:" }
entries[140472] = { ["name"] = "Ancient Nightborne Tome", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"The language is so archaic, only the oldest elves might be able to read it.\"" }
entries[140473] = { ["name"] = "Night-forged Halberd", ["text"] = "Binds when picked up\n\"Not a delicate or subtle weapon.\"\nSell Price:" }
entries[140474] = { ["name"] = "Nar'thalas Pottery Fragment", ["text"] = "Binds when picked up\n\"Once a fine work of art before being shattered decades ago.\"\nSell Price:" }
entries[140475] = { ["name"] = "Morning Glory Vine", ["text"] = "Binds when picked up\n\"This weed grows throughout the ruined sections of Suramar.\"\nSell Price:" }
entries[140476] = { ["name"] = "Astranaar Globe", ["text"] = "Binds when picked up\n\"Broken at some point during the siege by the orcs, it no longer spins.\"\nSell Price:" }
entries[140477] = { ["name"] = "Inert Ashes", ["text"] = "Binds when picked up\n\"Not everyone survived Archmage Khadgar's trials on Draenor.\"\nSell Price:" }
entries[140478] = { ["name"] = "Painted Bark", ["text"] = "Binds when picked up\n\"Life is a magical thing.\"\nSell Price:" }
entries[140479] = { ["name"] = "Broken Legion Communicator", ["text"] = "Binds when picked up\n\"It plays the same angry-sounding message over and over.\"\nSell Price:" }
entries[140480] = { ["name"] = "Drained Construct Core", ["text"] = "Binds when picked up\n\"It once powered a Nightborne Construct. Now it is only a pretty paperweight.\"\nSell Price:" }
entries[140481] = { ["name"] = "Shimmering Hourglass", ["text"] = "Binds when picked up\n\"Keeps very precise time - for someplace else entirely.\"\nSell Price:" }
entries[140482] = { ["name"] = "Storm Drake Fang", ["text"] = "Binds when picked up\n\"It's enormous, sharp, and contains no magic whatsoever. How disappointingly prosaic.\"\nSell Price:" }
entries[140483] = { ["name"] = "Jade Fragment", ["text"] = "Binds when picked up\nUse: Provides a significant increase to character experience. Does not work for players over level 49.\n\"Once a piece of a small serpent figurine.\"" }
entries[140484] = { ["name"] = "Well-Used Drinking Horn", ["text"] = "Binds when picked up\n\"It still smells of several kinds of brew.\"\nSell Price:" }
entries[140485] = { ["name"] = "Duskpelt Fang", ["text"] = "Binds when picked up\n\"Slightly chipped.\"\nSell Price:" }
entries[140486] = { ["name"] = "Storm Drake Scale", ["text"] = "Binds when picked up\n\"One of the soft, shiny underbelly scales.\"\nSell Price:" }
entries[140487] = { ["name"] = "War-Damaged Vrykul Helmet", ["text"] = "Binds when picked up\n\"A large piece of the face guard is missing.\"\nSell Price:" }
entries[140488] = { ["name"] = "Huge Blacksmith's Hammer", ["text"] = "Binds when picked up\n\"It's too large for a normal blacksmith.\"\nSell Price:" }
entries[140489] = { ["name"] = "Ettin Toe Ring", ["text"] = "Binds when picked up\n\"It could be used as a belt if not for the unbearable stench.\"\nSell Price:" }
entries[140490] = { ["name"] = "Wooden Snow Shoes", ["text"] = "Binds when picked up\n\"The Highmountain thought they were too small to use in the snow.\"\nSell Price:" }
entries[140491] = { ["name"] = "Stolen Pearl Ring", ["text"] = "Binds when picked up\n\"The harpies stole it and stuffed it under a nest.\"\nSell Price:" }
entries[140492] = { ["name"] = "Gleaming Glacial Pebble", ["text"] = "Binds when picked up\n\"Rubbed smooth by tons of ice and the passage of time.\"\nSell Price:" }
entries[140493] = { ["name"] = "Adept's Guide to Dimensional Rifting", ["text"] = "Binds when picked up\nUse: Teleport to an attuned Ley Line point in the Broken Isles. (4 Hrs Cooldown)\n\"This advanced guide allows access to the wider Ley Lines of the Broken Isles.\"\nSell Price:" }
entries[140494] = { ["name"] = "Eredar Tail-Cuff", ["text"] = "Binds when picked up\n\"The more decorative the cuff, the more prestigious the individual.\"\nSell Price:" }
entries[140495] = { ["name"] = "Torn Invitation", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Clearly an invitation to an exclusive Nightborne noble event.\"" }
entries[140496] = { ["name"] = "Fox Hunt Invitation", ["text"] = "Quest Item\n\"Further pieces of the puzzle.\"" }
entries[140497] = { ["name"] = "Bundle of Tiny Spears", ["text"] = "Binds when picked up\n\"Individually they are no more dangerous than a sewing needle. A score of them could do some serious damage.\"\nSell Price:" }
entries[140498] = { ["name"] = "Legion Admirer's Note", ["text"] = "Binds when picked up\n\"While undercover, someone passed this note expressing admiration.\"\nSell Price:" }
entries[140499] = { ["name"] = "Off-Colored Fel Stone", ["text"] = "Binds when picked up\nUse: Provides a significant increase to character experience. Does not work for players over level 49.\n\"Still warm to the touch.\"" }
entries[140500] = { ["name"] = "Mechanized Lumber Extractor", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to ride the Mechanized Lumber Extractor. This is a flying mount.\nMount a Mechanized Lumber Extractor, allowing you to fly very fast. The claws are surprisingly delicate and herbalists can use them to pick herbs! This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Jepetto may have over done it a little...\"\nAchievement:\nRemember to Share\nCategory:\nToy Box" }
entries[140501] = { ["name"] = "Outdated Intelligence", ["text"] = "Binds when picked up\nUse: Provides a significant increase to character experience. Does not work for players over level 49.\n\"At one point this would have been valuable information, a clerical error means it is now worthless.\"" }
entries[140502] = { ["name"] = "Tattered Eye Patch", ["text"] = "Binds when picked up\nUse: Provides a significant increase to character experience. Does not work for players over level 49.\n\"The former owner doesn't need it any more.\"\nSell Price:" }
