entries[140505] = { ["name"] = "Sweaty Bandanna", ["text"] = "Binds when picked up\n\"A poor facsimile of a pirate's swagger.\"\nSell Price:" }
entries[140507] = { ["name"] = "Unlabeled Potion", ["text"] = "Binds when picked up\n\"It's probably best not to drink it.\"\nSell Price:" }
