entries[140652] = { ["name"] = "Seed of Solar Fire", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Combine the Seed of Solar Fire with a Pure Drop of Shaladrassil's Sap to create a rare Sunbloom.\nRequires Dreamweavers\n- Exalted\n\"A brightly glowing seed from deep within the emerald dream. The Dreamweavers have never found the secret to making it bloom.\"\nSell Price:" }
entries[140653] = { ["name"] = "Pure Drop of Shaladrassil's Sap", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Combine the Seed of Solar Fire with a Pure Drop of Shaladrassil's Sap to create a rare Sunbloom.\n\"A single drop of glowing sap, rumored to possess the power to ignite life in even the most dormant remains.\"" }
entries[140654] = { ["name"] = "Pestilential Hide of Nythendra", ["text"] = "Quest Item\n\"The hide is almost completely eaten away by insects.\"" }
entries[140655] = { ["name"] = "Log", ["text"] = "Binds when picked up\nUnique\nUse: Summon an Unfinished Totem for 10 min. (10 Min Cooldown)\nRequires Highmountain Tribe\n- Revered\n\"It's big, it's heavy, it's wood.\"\nSell Price:" }
entries[140656] = { ["name"] = "Rod of the Ascended", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Combine the Crest of the Lightborn with the Rod of the Ascended to create the Staff of the Lightborn.\nRequires Valarjar\n- Exalted\n\"An exquisite staff, crafted to channel great power for a long-forgotten vrykul mystic. Without the right headpiece, the staff lies dormant.\"\nSell Price:" }
entries[140657] = { ["name"] = "Crest of the Lightborn", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Combine the Crest of the Lightborn with the Rod of the Ascended to create the Staff of the Lightborn.\n\"An intricate headpiece pulsing with holy power. With the right vessel to channel it, it could serve as a potent weapon of the Light.\"" }
entries[140658] = { ["name"] = "Skull of Nithogg", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nUse: Combine the Haft of the God-King with the Skull of Shar'thos and the Skull of Nithogg to create the Dragonslayers.\n\"A massive dragon skull, still crackling with Nithogg's thunderous power.\"" }
entries[140659] = { ["name"] = "Skull of Shar'thos", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nUse: Combine the Haft of the God-King with the Skull of Shar'thos and the Skull of Nithogg to create the Dragonslayers.\n\"A massive dragon skull, still thrumming with Shar'thos' nightmarish power.\"" }
entries[140660] = { ["name"] = "Haft of the God-King", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nUse: Combine the Haft of the God-King with the Skull of Shar'thos and the Skull of Nithogg to create the Dragonslayers.\n\"A massive haft to a greataxe, but with no axe-head. Mystic vrykul runes run the length of the wood. Too large for a non-vrykul warrior, the haft is segmented in a way that it might easily be split into shafts for 2 axes...\"" }
