entries[141035] = { ["name"] = "Technique: Glyph of Fel Wings", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Fel Wings.\nCraft a Glyph of Fel Wings.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Fel Wings\nClasses: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYou now have green wings when Glide is active. Exclusive with: Glyph of Fallow Wings Glyph of Tattered Wings\nSell Price:\nRequires Light Parchment , Sallow Pigment (12), Roseate Pigment (20)" }
entries[141036] = { ["name"] = "Technique: Glyph of Fel-Enemies", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Fel-Enemies.\nCraft a Glyph of Fel-Enemies.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Fel-Enemies\nClasses: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYour Spectral Sight is altered by Fel energy causing you to see all enemies in a Fel light.\nSell Price:\nRequires Light Parchment , Sallow Pigment (12), Roseate Pigment (20)" }
entries[141037] = { ["name"] = "Technique: Glyph of Mana Touched Souls", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Mana Touched Souls.\nCraft a Glyph of Mana Touched Souls.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Mana Touched Souls\nClasses: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYour Shattered Souls are tainted with mana. Exclusive with: Glyph of Fel Touched Souls\nSell Price:\nRequires Light Parchment , Sallow Pigment (12), Roseate Pigment (20)" }
entries[141038] = { ["name"] = "Technique: Glyph of Shadow-Enemies", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Shadow-Enemies.\nCraft a Glyph of Shadow-Enemies.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Shadow-Enemies\nClasses: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYour Spectral Sight is tinted by the void and you see enemies shrouded in Shadow.\nSell Price:\nRequires Light Parchment , Sallow Pigment (12), Roseate Pigment (20)" }
entries[141039] = { ["name"] = "Technique: Glyph of the Doe", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of the Doe.\nCraft a Glyph of the Doe.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of the Doe\nClasses: Druid\nUse: Unlocks the Doe Travel Form option at the Barber Shop.\nSell Price:\nRequires Light Parchment , Sallow Pigment (4), Roseate Pigment (60)" }
entries[141040] = { ["name"] = "Technique: Glyph of the Feral Chameleon", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of the Feral Chameleon.\nCraft a Glyph of the Feral Chameleon.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of the Feral Chameleon\nClasses: Druid\nUse: Permanently teaches you this glyph.\n\nEach time you shapeshift into Cat Form, your shapeshifted form will be randomly selected.\nSell Price:\nRequires Light Parchment , Sallow Pigment (4), Roseate Pigment (60)" }
entries[141041] = { ["name"] = "Technique: Glyph of the Forest Path", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of the Forest Path.\nCraft a Glyph of the Forest Path.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of the Forest Path\nClasses: Druid\nUse: Permanently teaches you this glyph.\n\nYour Dash now leaves a trail of leaves.\nSell Price:\nRequires Light Parchment , Sallow Pigment (4), Roseate Pigment (60)" }
entries[141042] = { ["name"] = "Technique: Glyph of Autumnal Bloom", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Autumnal Bloom.\nCraft a Glyph of Autumnal Bloom.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Autumnal Bloom\nClasses: Druid\nUse: Permanently teaches you this glyph.\n\nModifies your Lifebloom to appear as a large blooming autumn flower.\nSell Price:\nRequires Light Parchment , Sallow Pigment (4), Roseate Pigment (60)" }
entries[141043] = { ["name"] = "Technique: Glyph of Arachnophobia", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Arachnophobia.\nCraft a Glyph of Arachnophobia.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Arachnophobia\nClasses: Hunter\nUse: Permanently teaches you this glyph.\n\nYour Dire Beast ability calls on spiders more often. Why? Because everyone is afraid of spiders. Exclusive with: Glyph of Nesingwary's Nemeses Glyph of the Dire Stable Glyph of Dire Bees\nSell Price:\nRequires Light Parchment , Sallow Pigment (8), Roseate Pigment (40)" }
entries[141044] = { ["name"] = "Technique: Glyph of Nesingwary's Nemeses", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Nesingwary's Nemeses.\nCraft a Glyph of Nesingwary's Nemeses.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Nesingwary's Nemeses\nClasses: Hunter\nUse: Permanently teaches you this glyph.\n\nYour Dire Beast ability often calls for beasts victimized by the famed hunter. Exclusive with: Glyph of Arachnophobia Glyph of the Dire Stable Glyph of Dire Bees\nSell Price:\nRequires Light Parchment , Sallow Pigment (8), Roseate Pigment (40)" }
