entries[141046] = { ["name"] = "Technique: Glyph of the Dire Stable", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of the Dire Stable.\nCraft a Glyph of the Dire Stable.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of the Dire Stable\nClasses: Hunter\nUse: Permanently teaches you this glyph.\n\nYour Dire Beast often calls forth dire versions of your stabled pets. Exclusive with: Glyph of Arachnophobia Glyph of Nesingwary's Nemeses Glyph of Dire Bees\nSell Price:\nRequires Light Parchment , Sallow Pigment (8), Roseate Pigment (40)" }
entries[141047] = { ["name"] = "Technique: Glyph of the Goblin Anti-Grav Flare", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of the Goblin Anti-Grav Flare.\nCraft a Glyph of the Goblin Anti-Grav Flare.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of the Goblin Anti-Grav Flare\nClasses: Hunter\nUse: Permanently teaches you this glyph.\n\nExchange your flares with Goblin Anti-Grav Flares! They almost work, and at least they don't explode. Exclusive with: Glyph of Stellar Flare\nSell Price:\nRequires Light Parchment , Sallow Pigment (8), Roseate Pigment (40)" }
